import sys
data = sys.stdin.read().split()
if data:
    n, target = int(data[0]), int(data[1])
    nums = [int(x) for x in data[2:2+n]]
    if sum(nums) < target: print(-1); sys.exit(0)
    counts = [0] * 32
    for x in nums:
        counts[x.bit_length() - 1] += 1
    ans = 0
    for i in range(31):
        if (target >> i) & 1:
            if counts[i] > 0: counts[i] -= 1
            else:
                j = i
                while j < 31 and counts[j] == 0: j += 1
                counts[j] -= 1
                while j > i:
                    j -= 1
                    counts[j] += 1
                    ans += 1
        counts[i + 1] += counts[i] // 2
    print(ans)
